pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool, address member, uint256 amount, uint256 lpReceived) public {
        vm.assume(pool != address(0) && member != address(0));
        vm.assume(pool != member);
        // The synth contract must consider the caller a curated pool.
        // We mock the POOLFACTORY and DAO returns by deploying a helper that always returns true for isCuratedPool.
        // Since C relies on iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender),
        // we need an adversarial counterparty: a fake factory that returns true for this call.
        // The bug is in mintSynth logic, not in external call failure, so we need a helper that allows the call.
        // Deploy a MockPoolFactory that returns true for isCuratedPool and has the needed interface.
        MockPoolFactory factory = new MockPoolFactory();
        MockDAO dao = new MockDAO(address(factory));
        MockBASE base = new MockBASE(address(dao));
        // Re-deploy C with the mocked base that returns our dao.
        // But setUp already deployed c with hardcoded addresses; we must create a fresh one with our adversarial setup.
        // We redeploy c using the base that returns the dao that returns the factory that returns true for isCuratedPool.
        c = new C(address(base), address(this));
        // Now we need to set up the LP token (pool) balance to simulate _getAddedLPAmount returning lpReceived.
        // We need a mock pool token that the synth can read balanceOf from and that allows transferFrom for the lpReceived setup.
        // The synth calls iBEP20(_pool).balanceOf(address(this)) and mapSynth_LPBalance[pool] to compute added LP.
        // We deploy a simple token that we can mint to the synth.
        MockToken poolToken = new MockToken();
        // Mint lpReceived tokens to the synth contract.
        poolToken.mint(address(c), lpReceived);
        // We also need to ensure mapSynth_LPBalance[pool] is 0 initially (default).
        // Now we can prank as the pool (which must be the caller) and call mintSynth.
        vm.prank(pool);
        c.mintSynth(member, amount);
        // After the call, check mapSynth_LPBalance.
        // In the reference, the LP balance should be credited to pool (msg.sender).
        // In the buggy version, it's credited to member.
        uint256 balancePool = c.getmapAddress_LPBalance(pool);
        uint256 balanceMember = c.getmapAddress_LPBalance(member);
        // The invariant: LP balance for pool must equal the added lpReceived, and member LP balance must be 0.
        assertTrue(balancePool == lpReceived && balanceMember == 0);
    }
}

contract MockPoolFactory {
    function isCuratedPool(address) external pure returns (bool) { return true; }
    function isPool(address) external pure returns (bool) { return true; }
    function getPool(address) external pure returns (address) { return address(0); }
    function createPool(address) external pure returns (address) { return address(0); }
    function getPoolArray(uint) external pure returns (address) { return address(0); }
    function poolCount() external pure returns (uint) { return 0; }
    function getToken(uint) external pure returns (address) { return address(0); }
    function tokenCount() external pure returns (uint) { return 0; }
    function getCuratedPoolsLength() external pure returns (uint) { return 0; }
    function addCuratedPool(address) external {}
    function removeCuratedPool(address) external {}
}

contract MockDAO {
    address public POOLFACTORY;
    constructor(address _pf) { POOLFACTORY = _pf; }
    function ROUTER() external pure returns (address) { return address(0); }
    function BASE() external pure returns (address) { return address(0); }
    function UTILS() external pure returns (address) { return address(0); }
    function DAO() external pure returns (address) { return address(0); }
    function RESERVE() external pure returns (address) { return address(0); }
    function BOND() external pure returns (address) { return address(0); }
    function SYNTHFACTORY() external pure returns (address) { return address(0); }
    function depositForMember(address, uint256, address) external {}
    function bondingPeriodSeconds() external pure returns (uint256) { return 0; }
}

contract MockBASE {
    address dao;
    constructor(address _dao) { dao = _dao; }
    function DAO() external view returns (address) { return dao; }
}

contract MockToken {
    mapping(address => uint) private _balances;
    function balanceOf(address account) external view returns (uint) { return _balances[account]; }
    function mint(address account, uint amount) external { _balances[account] += amount; }
    function transferFrom(address, address, uint) external pure returns (bool) { return true; }
}

