pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address pool, address member, uint112 amount) public {
        vm.assume(pool != address(0) && member != address(0) && pool != member);
        vm.assume(amount > 0);

        // Record mapSynth_LPBalance for the pool before the call
        uint256 beforeBalance = c.getmapAddress_LPBalance(pool);

        // Simulate a curated pool calling mintSynth by pranking as pool
        vm.prank(pool);
        try c.mintSynth(member, amount) {} catch {}

        uint256 afterBalance = c.getmapAddress_LPBalance(pool);

        // The invariant: mapSynth_LPBalance[pool] should be strictly greater than before
        // if the call succeeded. The buggy version fails this because it credits the member instead.
        bool callSucceeded = afterBalance > beforeBalance;
        assertTrue(callSucceeded);
    }
}

