pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address pool1, address pool2, address member1, address member2, uint256 amount1, uint256 amount2) public {
        vm.assume(pool1 != address(0) && pool2 != address(0) && member1 != address(0) && member2 != address(0));
        vm.assume(pool1 != pool2 && member1 != member2);
        vm.assume(amount1 > 0 && amount2 > 0);

        // Setup: prank as pool1 and pool2 to call mintSynth
        vm.startPrank(pool1);
        c.mintSynth(member1, amount1);
        vm.stopPrank();

        vm.startPrank(pool2);
        c.mintSynth(member2, amount2);
        vm.stopPrank();

        // Sum of all LP balances should equal sum of all LP debts
        uint256 totalBalance = c.mapSynth_LPBalance(pool1) + c.mapSynth_LPBalance(pool2) + c.mapSynth_LPBalance(member1) + c.mapSynth_LPBalance(member2);
        uint256 totalDebt = c.mapSynth_LPDebt(pool1) + c.mapSynth_LPDebt(pool2) + c.mapSynth_LPDebt(member1) + c.mapSynth_LPDebt(member2);
        assertTrue(totalBalance == totalDebt);
    }
}

