pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MintSynthHelper {
    C public synth;
    constructor(address _synth) {
        synth = C(_synth);
    }
    function callMintSynth(address member, uint256 amount) external {
        synth.mintSynth(member, amount);
    }
}

contract InvMutTest is Test {
    C c;
    address pool = address(0x1234);
    MintSynthHelper helper;

    function setUp() public {
        c = new C(address(this), address(this));
        helper = new MintSynthHelper(address(c));
        vm.etch(pool, address(helper).code);
    }

    function testFuzz_property(address member, uint256 amount) public {
        vm.assume(member != address(0) && member != pool);
        vm.assume(amount > 0 && amount < type(uint128).max);

        uint256 lpBalanceBefore = c.getmapAddress_LPBalance(pool);
        uint256 lpDebtBefore = c.getmapAddress_LPDebt(pool);
        uint256 memberBalanceBefore = c.getmapAddress_LPBalance(member);
        uint256 memberDebtBefore = c.getmapAddress_LPDebt(member);

        vm.prank(pool);
        c.mintSynth(member, amount);

        uint256 lpBalanceAfter = c.getmapAddress_LPBalance(pool);
        uint256 lpDebtAfter = c.getmapAddress_LPDebt(pool);
        uint256 memberBalanceAfter = c.getmapAddress_LPBalance(member);
        uint256 memberDebtAfter = c.getmapAddress_LPDebt(member);

        uint256 totalBalanceBefore = lpBalanceBefore + memberBalanceBefore;
        uint256 totalDebtBefore = lpDebtBefore + memberDebtBefore;
        uint256 totalBalanceAfter = lpBalanceAfter + memberBalanceAfter;
        uint256 totalDebtAfter = lpDebtAfter + memberDebtAfter;

        assertTrue(totalBalanceAfter - totalBalanceBefore == totalDebtAfter - totalDebtBefore - amount);
    }
}

contract InvMutTest {
    C c;
    address synth;
    constructor(C _c) public {
        c = _c;
    }
    function test(address account, uint amount) public returns (bool) {
        uint lpBalBefore = c.mapSynth_LPBalance(address(this));
        uint lpDebtBefore = c.mapSynth_LPDebt(address(this));
        c.mintSynth(account, amount);
        uint lpBalAfter = c.mapSynth_LPBalance(address(this));
        uint lpDebtAfter = c.mapSynth_LPDebt(address(this));
        assert(lpBalAfter - lpBalBefore <= amount && lpDebtAfter - lpDebtBefore == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address pool) public payable {
        require(amount > 0);
        uint lpBalanceBefore = c.mapSynth_LPBalance(pool);
        // This reads the pool token balance of this contract using a public getter of the pool contract
        // The pool is a Pool contract that implements iBEP20, so balanceOf is public
        uint poolTokenBalanceBefore = iBEP20(pool).balanceOf(address(this));
        bool reverted; try c.mintSynth(address(this), amount) { reverted = false; } catch { reverted = true; }
        uint lpBalanceAfter = c.mapSynth_LPBalance(pool);
        uint poolTokenBalanceAfter = iBEP20(pool).balanceOf(address(this));
        assert(!reverted ? (lpBalanceAfter - lpBalanceBefore == poolTokenBalanceAfter - poolTokenBalanceBefore) : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address member, uint amount, address pool) public payable {
        require(true);
        uint preLPBal = iBEP20(pool).balanceOf(address(c));
        uint preMap = c.getmapAddress_LPBalance(pool);
        bool reverted;
        try c.mintSynth(member, amount) { reverted = false; } catch { reverted = true; }
        uint postLPBal = iBEP20(pool).balanceOf(address(c));
        uint postMap = c.getmapAddress_LPBalance(pool);
        assert(reverted || (postMap - preMap) == (postLPBal - preLPBal));
    }
    receive() external payable {}
}

